export function cartTotal(items) {
  return items.reduce((t, i) => t + i.price, 0);
}

args.content:
export function cartTotal(items) {
  return items.reduce((t, i) => t + i.price * i.qty, 0);
}

files.src/clamp.js:
export function clamp(n, lo, hi) {
  return Math.min(lo, Math.max(n, hi));
}

files.tests/clamp.test.js:
import { clamp } from '../src/clamp.js';
test('inside', () => expect(clamp(5, 0, 10)).toBe(5));
test('above', () => expect(clamp(15, 0, 10)).toBe(10));

args.content:
export function clamp(n, lo, hi) {
  return Math.min(hi, Math.max(n, lo));
}

